INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_7a4c_001','mer_7a4c19d2','user_scm_lin',5,'The guide comes from the production line and can explain the processes clearly. The team of forty can move along the route in two groups without crowding.','["Visitor corridor"]','2026-03-14T08:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_7a4c_002','mer_7a4c19d2','user_hr_zhou',4,'The safety briefing was very thorough: before entering the workshop, they checked each person''s shoes and worn protective equipment. The drawback was that photography was prohibited throughout, so the team photo could only be taken in the lobby afterward.','[]','2026-04-02T09:30:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_7a4c_003','mer_7a4c19d2','user_ops_chen',5,'The high-decibel noise in the stamping area is indeed loud. They provided earplugs in advance, and the briefing also reminded everyone that those experiencing hearing discomfort could watch from outside the observation window.','[]','2026-04-21T02:15:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_7a4c_004','mer_7a4c19d2','user_qc_wang',4,'The invoicing is very standardized, and the company name can be printed the same day. Pay attention to the deposit terms; it would be best to have Legal review them before signing.','[]','2026-05-08T06:40:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_7a4c_005','mer_7a4c19d2','user_pm_xu',5,'Lunch was not handled on site; we walked out of the park to eat, which took approximately 15 minutes round trip. This time must be factored into the schedule.','[]','2026-05-30T03:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_7a4c_006','mer_7a4c19d2','user_admin_he',3,'Dust was noticeably heavy around the grinding workstations, and some colleagues left partway through for the rest area. The host arranged this fairly promptly.','[]','2026-06-11T07:20:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_c28f_001','mer_c28f6b41','user_scm_lin',2,'The quote was indeed low, but they required scans of the original identification documents for all personnel in advance for security pre-screening. We declined, so the arrangement was canceled.','[]','2026-03-19T05:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_c28f_002','mer_c28f6b41','user_hr_zhou',2,'The contract states that the deposit is nonrefundable and rescheduling is not accepted, leaving no flexibility at all if the group size changes.','[]','2026-04-26T05:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_c28f_003','mer_c28f6b41','user_ops_chen',3,'The on-site experience is lively, but the forklift lanes and visitor routes are separated only by traffic cones, so the sense of safety is average.','[]','2026-05-15T05:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_lunch_001','mer_5e91a7c3','user_pm_xu',5,'The private room can seat 40-plus people, dishes are served quickly, and vegetarian and halal food are prepared on separate stoves with clear labeling.','["Private-room panorama"]','2026-02-27T04:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_lunch_002','mer_5e91a7c3','user_qc_wang',5,'There are no additional requirements for putting the company''s name on the invoice; it will be issued on the spot at checkout, and the payment terms are negotiable.','[]','2026-03-25T04:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_lunch_003','mer_5e91a7c3','user_admin_he',4,'About a ten-minute drive from the industrial park; parking is tight at noon, so buses should preferably park at the side entrance on Huayuan Road.','[]','2026-04-30T04:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_lunch_004','mer_5e91a7c3','user_scm_lin',4,'Special dietary requirements can be reported one day in advance, but adding them on the day itself will be too late; they will simply say they cannot accommodate them.','[]','2026-06-06T04:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_hzbay_001','mer_v_hangzhou_bay','user_ops_chen',5,'The cleanliness level in the new materials workshop is very high, but everyone is required to change into a full set of coveralls; it took 30 minutes for 40 people to change.','[]','2026-03-08T06:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_hzbay_002','mer_v_hangzhou_bay','user_pm_xu',4,'The one-way trip from Shanghai takes nearly two hours, so a same-day round trip would be rushed; it is recommended to arrange lunch nearby.','[]','2026-05-12T06:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_tongxiang_001','mer_v_tongxiang_textile','user_hr_zhou',4,'The textile workshop has continuous high-decibel noise that is not piercing but lasts for a long time, so wireless tour-guide headsets must be used throughout the briefing.','[]','2026-04-16T03:30:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_tongxiang_002','mer_v_tongxiang_textile','user_admin_he',4,'They can accommodate a 90-person group, with the briefing conducted in three groups simultaneously; their organizational capability is better than expected.','[]','2026-06-01T03:30:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_haining_001','mer_v_haining_leather','user_qc_wang',3,'The hands-on craft experience is suitable for small groups of around a dozen people; with more than 40 people, the queues become so long that people lose patience.','[]','2026-02-19T07:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_jiashan_001','mer_v_jiashan_logistics','user_scm_lin',5,'The automated high-bay warehouse is very impressive and closely resembles our own warehousing scenarios; our colleagues had a lively discussion.','["Main aisle of the automated warehouse"]','2026-05-21T02:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_jiashan_002','mer_v_jiashan_logistics','user_ops_chen',4,'AGVs operate next to the visitor route, and the host requires everyone to proceed in a single file on the right throughout; the rules are fairly strict.','[]','2026-06-18T02:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_pinghu_001','mer_v_pinghu_auto','user_pm_xu',5,'There is a twenty-minute safety briefing and sign-in before entry, and the process is well organized; the overall schedule just needs an extra half day.','[]','2026-04-09T08:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_nanhu_museum_001','mer_v_nanhu_museum','user_admin_he',4,'The indoor areas are air-conditioned throughout, making this a suitable alternative for hot days or colleagues with limited physical stamina.','[]','2026-06-25T05:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_xiuzhou_001','mer_v_xiuzhou_park','user_qc_wang',4,'The meeting room''s projection and audio systems are both usable, and it can accommodate sessions for 150 people; the downside is that no catering is available.','[]','2026-05-04T09:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_yangpu_001','mer_v_sh_yangpu_maker','user_hr_zhou',4,'There is no need to charter a bus within the city, as the metro goes directly there, but open-day slots are highly competitive, and popular sessions fill up two weeks in advance.','[]','2026-03-31T06:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_minhang_001','mer_v_sh_minhang_lab','user_scm_lin',4,'Each visitor to the cleanroom must sign a confidentiality undertaking; we spent a week going through the internal review process before finalizing this.','[]','2026-04-23T06:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_qingpu_001','mer_v_qingpu_hall','user_pm_xu',4,'The wrap-up event for last autumn''s open day was held here. The venue is familiar, and the buffet was average.','[]','2025-10-26T10:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_songjiang_001','mer_v_songjiang_camp','user_ops_chen',2,'The outdoor team-building activity is too strenuous. A colleague suffered heatstroke last year, so we really do not recommend scheduling this kind of activity again in summer.','[]','2025-08-17T09:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_hexiang_001','mer_r_hexiang_banquet','user_admin_he',4,'The banquet hall is grand, and even with 24 tables operating simultaneously, it does not feel chaotic, but the per-person cost is relatively high, so it is not very suitable for routine team-building.','[]','2026-01-20T12:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_qingzhen_001','mer_r_qingzhen_yuan','user_qc_wang',5,'Halal credentials are complete, Hui colleagues can dine with complete peace of mind, and private rooms must be booked three days in advance.','[]','2026-03-06T11:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_suwei_001','mer_r_sushi_veg','user_hr_zhou',4,'The all-vegetarian menu is flavorful rather than bland, and the venue capacity of 45 people is just at the edge of our team size.','[]','2026-05-19T11:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_haixian_001','mer_r_haixian_lou','user_pm_xu',3,'The food tasted good, but they only mentioned at checkout that the service fee was charged separately, which makes reimbursement fairly troublesome.','[]','2026-02-11T12:30:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_hotpot_001','mer_r_jiashan_hotpot','user_scm_lin',3,'Hot pot is lively, to be sure, but having forty people crammed together in summer makes for an average experience, and everyone''s clothes smell afterward.','[]','2026-06-13T13:00:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_canteen_001','mer_r_jiaxing_canteen','user_ops_chen',3,'The park cafeteria is open only to enterprises in the park; outside teams must file in advance, and the application must be submitted by an enterprise in the park.','[]','2026-04-07T04:30:00Z');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_acmaintain_001','mer_h_ac_maintain','user_admin_he',4,'They handle the annual air-conditioning maintenance for Headquarters; their response is fast, and the quote is calculated based on the number of cabinet units.','[]','2026-06-02T08:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_factory_capacity','mer_7a4c19d2','user_scm_lin','How many people can be accommodated per session at most?','The limit is 80 people per session; if there are more than 40 people, they will be split into 2 groups to enter the workshop at staggered times.','merchant','2026-03-02T01:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_factory_ppe','mer_7a4c19d2','user_hr_zhou','Are hard hats and earplugs brought by us or provided on site?','Basic safety helmets and high-visibility vests are provided onsite; earplugs and dust masks are part of the upgrade package and require separate confirmation.','merchant','2026-03-28T01:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_factory_route','mer_7a4c19d2','user_ops_chen','Will the tour route pass through the forklift operating area?','There is a fixed guardrail between the main route and the forklift lane; only at loading and unloading observation points will people observe from across the barrier.','merchant','2026-04-18T01:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_factory_exit','mer_7a4c19d2','user_qc_wang','Can I leave if I feel unwell partway through?','Yes. There is a rest area on every floor, and the guide will arrange for an accompanying staff member to lead them out without affecting the others'' continued visit.','merchant','2026-05-22T01:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_factory_deposit','mer_7a4c19d2','user_pm_xu','When and how should the deposit be paid, and how is it refunded?','After the schedule is confirmed, pay the deposit; it will be refunded via the original payment method within fifteen working days after the visit is completed, and payment must be made through a corporate account.','merchant','2026-06-09T01:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_factory_lang','mer_7a4c19d2','user_admin_he','Is there any interpretation in languages other than Chinese?','The tour briefing is currently available only in Chinese; written safety instructions can be prepared separately as needed.','merchant','2026-06-20T01:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_c28f_id','mer_c28f6b41','user_scm_lin','What materials are required for the security pre-review?','Complete identification details for everyone must be submitted in advance for registration in the industrial park security system.','merchant','2026-03-16T02:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_c28f_refund','mer_c28f6b41','user_hr_zhou','Can the booking be rescheduled or refunded if the headcount changes?','Once the deposit is paid, it will not be refunded, and the scheduled date generally cannot be adjusted.','merchant','2026-04-24T02:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_lunch_diet','mer_5e91a7c3','user_seed_tb_013','How should vegetarian and halal meals be arranged?','Vegetarian and halal meals are prepared in separate kitchens and served separately; please report the headcount and number of tables one day in advance.','merchant','2026-06-07T03:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_lunch_invoice','mer_5e91a7c3','user_qc_wang','Can you issue an invoice bearing the company''s name?','A standard VAT invoice can be issued; the company name and tax identification number only need to be provided at checkout.','merchant','2026-05-02T03:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_lunch_park','mer_5e91a7c3','user_admin_he','Is Parking Convenient for Coaches?','Buses cannot stop at the entrance; temporary parking spaces are available by the side entrance on Huayuan Road, about a three-minute walk away.','merchant','2026-04-28T03:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_tongxiang_group','mer_v_tongxiang_textile','user_pm_xu','How should a 90-person team be divided into groups?','Enter different workshops simultaneously in three groups, with one guide and one safety officer assigned to each group.','merchant','2026-05-27T04:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_jiashan_agv','mer_v_jiashan_logistics','user_ops_chen','What requirements apply to visiting the AGV area?','You must proceed in single file along the yellow boundary line; crossing the line to take photos or stopping there is prohibited.','merchant','2026-06-16T04:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_minhang_nda','mer_v_sh_minhang_lab','user_scm_lin','Does each person sign the confidentiality commitment, or does the company sign it?','Each person entering the premises must sign in person; a company-stamped version is not accepted.','merchant','2026-04-20T04:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_qingpu_pkg','mer_v_qingpu_hall','user_admin_he','How is the package price for the venue plus buffet calculated?','Tiered by headcount, starting at 380 yuan per person for groups of more than 40, including four hours of venue use.','merchant','2025-10-08T04:00:00Z');
INSERT INTO merchant_qa(qa_id,merchant_id,user_id,question,answer,answered_by,created_at) VALUES ('qa_songjiang_heat','mer_v_songjiang_camp','user_hr_zhou','Are there heatstroke-prevention arrangements for the summer?','The camp provides sun shelters and drinking water, but outdoor activities will be canceled temporarily on days with a high-temperature warning.','merchant','2026-06-05T04:00:00Z');
